// เตรียมไฟล์ส่งเข้า Typhoon OCR ในเครื่อง (ไม่ต้องสร้าง request ของ Claude แล้ว)
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.data) {
    out.push({ json: { ...item.json, skip: true, error: 'ไม่พบไฟล์แนบ' } });
    continue;
  }
  out.push({
    json: { ...item.json, upload_id: $('Webhook').first().json.body.upload_id },
    binary: { data: item.binary.data },
  });
}
return out;

const PROMPT = `คุณคือระบบสกัดข้อมูลจากข้อความ OCR ของเอกสารการเงินภาษาไทย/อังกฤษ
ประเภทเอกสาร (doc_type): SLIP=สลิปโอนเงินธนาคาร, OP=ใบสั่งซื้อ, INV=ใบแจ้งหนี้, BN=ใบวางบิล, RC=ใบเสร็จรับเงิน, TX=ใบกำกับภาษี
ตอบเป็น JSON เท่านั้น ห้ามมีคำอธิบายหรือ markdown ตามโครงสร้างนี้ ช่องที่ไม่เกี่ยวกับประเภทเอกสารให้ใส่ null หรือ []:
{"doc_type":string,"doc_no":string|null,"ref_no":string|null,"customer_po_no":string|null,"customer_name":string|null,"tax_id":string|null,"address":string|null,"email":string|null,"issue_date":"YYYY-MM-DD"|null,"due_date":"YYYY-MM-DD"|null,"items":[{"description":string,"qty":number,"unit_price":number}],"subtotal":number|null,"vat":number|null,"total":number|null,"invoice_refs":[{"doc_no":string,"amount":number}],"transfer_datetime":"YYYY-MM-DDTHH:mm:ss"|null,"amount":number|null,"sender_name":string|null,"receiver_name":string|null,"bank":string|null,"memo":string|null,"confidence":number}
กติกา:
- ห้ามแปลภาษา คัดลอกข้อความตามต้นฉบับ ถ้าอ่านไม่ออกให้ใส่ null ห้ามเดา
- ปี พ.ศ. ให้แปลงเป็น ค.ศ. (ลบ 543) ตัวเลขห้ามมีเครื่องหมายจุลภาค
- doc_no คือเลขที่ของเอกสารใบนั้นเอง
- ref_no คือเลขเอกสารก่อนหน้าที่อ้างถึง (ใบแจ้งหนี้อ้างใบสั่งซื้อ, ใบเสร็จอ้างใบแจ้งหนี้) แต่ถ้าเป็นสลิปให้ใส่รหัสอ้างอิงของธนาคาร
- customer_name คือลูกค้า/ผู้ซื้อ ไม่ใช่ผู้ออกเอกสารและไม่ใช่ผู้ลงนาม
- ใบวางบิล (BN): ใส่แต่ละแถวใน invoice_refs (doc_no = เลขที่ใบแจ้งหนี้, amount = จำนวนเงิน) และ items เป็น []
- สลิป (SLIP): ใช้ amount, sender_name, receiver_name, bank, transfer_datetime, memo (บันทึกช่วยจำที่ผู้โอนพิมพ์) และ items เป็น []
- confidence คือความมั่นใจรวม 0-1`;
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const text = r.success && r.text ? r.text : '';
  const ocrError = text ? null : (r.error?.message || (r.error ? JSON.stringify(r.error) : 'OCR ไม่ได้ข้อความ'));
  out.push({ json: {
    ocr_error: ocrError,
    ocr_text: text,
    extract_request: {
      model: 'scb10x/llama3.1-typhoon2-8b-instruct:latest',
      stream: false, format: 'json',
      options: { temperature: 0, num_ctx: 8192 },
      messages: [
        { role: 'system', content: PROMPT },
        { role: 'user', content: 'ข้อความ OCR ของเอกสาร:\n\n' + (text || '(ไม่มีข้อความ)') },
      ],
    },
  } });
}
return out;

const parseJson = (t) => {
  const s = String(t || '').replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  return JSON.parse(s.slice(a, b + 1));
};
const src = { ...$('Build OCR request').first().json, upload_id: $('Webhook').first().json.body.upload_id };
const ext = $('Build extract request').first().json;
const r = $input.first().json;
const fail = (msg) => [{ json: { upload_id: src.upload_id, error: msg } }];
if (src.skip) return fail(src.error);
if (ext.ocr_error) return fail('OCR ล้มเหลว: ' + ext.ocr_error);
if (r.error || !r.message?.content) return fail('สกัดข้อมูลจาก OCR ไม่สำเร็จ: ' + (r.error?.message || JSON.stringify(r.error || '')));
try {
  return [{ json: { upload_id: src.upload_id, ocr: parseJson(r.message.content), ocr_text: ext.ocr_text } }];
} catch (e) {
  return fail('อ่านผลลัพธ์ OCR ไม่ได้: ' + e.message);
}
